// Verifies X-MinMurasu-Signature = sha256=HMAC_SHA256(secret, `${timestamp}.${rawBody}`)
// Self-hosted n8n: set NODE_FUNCTION_ALLOW_BUILTIN=crypto so require('crypto') works.
const crypto = require('crypto');

// Paste the same value as LEAD_WEBHOOK_SECRET in Vercel / .env.local.
const SECRET = 'PASTE_LEAD_WEBHOOK_SECRET_HERE';

const item = $input.first();
const headers = item.json.headers || {};
const ts = headers['x-minmurasu-timestamp'];
const sig = String(headers['x-minmurasu-signature'] || '');

let raw;
try {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} catch (e) {
  // The site sends compact JSON.stringify output, so re-serialising is byte-identical.
  raw = JSON.stringify(item.json.body);
}

const expected = 'sha256=' + crypto.createHmac('sha256', SECRET).update(`${ts}.${raw}`).digest('hex');
const fresh = Boolean(ts) && Math.abs(Date.now() / 1000 - Number(ts)) < 300;
const valid = fresh && sig.length === expected.length &&
  crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected));

const payload = valid ? JSON.parse(raw) : null;
return [{ json: { valid, event: payload?.event ?? null, lead: payload?.lead ?? null } }];
